import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";

type SB = any;

type DailyReheatSettings = {
  id: string;
  enabled: boolean;
  live_dispatch_enabled: boolean;
  daily_whapi_cap: number;
  queue_a_wait_minutes: number;
  queue_a_silence_hours: number;
  cooldown_hours: number;
  cold_min_age_hours: number;
  window_start_brt: string;
  window_end_brt: string;
  weekdays_only: boolean;
  flow_variant: string;
  priority_queue: "A_then_B" | "B_then_A" | "A_only" | "B_only";
  pilot_consultant_ids: string[];
};

type PlannedAction =
  | "open_attendance"
  | "send_audio"
  | "start_flow"
  | "call"
  | "sms"
  | "close_rating"
  | "wait";

type CandidatePlan = {
  customer_id: string;
  consultant_id: string | null;
  queue: "A" | "B";
  step: string;
  phone_tail: string;
  name: string | null;
  planned_actions: PlannedAction[];
  would_consume_whapi: boolean;
  would_call: boolean;
  would_sms: boolean;
  reason: string;
  guards: string[];
};

const TERMINAL_STEPS = new Set([
  "complete",
  "portal_submitting",
  "portal_submitted",
  "registered_igreen",
  "awaiting_signature",
  "finalizando",
  "validando_otp",
  "aguardando_humano",
  "aguardando_avaliacao_atendimento",
  "atendimento_finalizado",
]);

function cycleDateBRT(now = new Date()): string {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(now);
}

function isWithinCommercialWindow(
  settings: DailyReheatSettings,
  now = new Date(),
): { ok: boolean; reason?: string } {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "America/Sao_Paulo",
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).formatToParts(now);

  const weekday = parts.find((p) => p.type === "weekday")?.value ?? "";
  const hour = Number(parts.find((p) => p.type === "hour")?.value ?? "0");
  const minute = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
  const minutes = hour * 60 + minute;

  if (settings.weekdays_only) {

    if (weekday === "Sat" || weekday === "Sun") {
      return { ok: false, reason: "weekend" };
    }
  }

  const [sh, sm] = settings.window_start_brt.slice(0, 5).split(":").map(Number);
  const [eh, em] = settings.window_end_brt.slice(0, 5).split(":").map(Number);
  const start = sh * 60 + sm;
  const end = eh * 60 + em;
  if (minutes < start || minutes > end) {
    return { ok: false, reason: "outside_window" };
  }
  return { ok: true };
}

async function loadDailyReheatSettings(supabase: SB): Promise<DailyReheatSettings> {
  const { data } = await supabase
    .from("daily_reheat_settings")
    .select("*")
    .eq("id", "global")
    .maybeSingle();

  return {
    id: "global",
    enabled: !!(data as any)?.enabled,
    live_dispatch_enabled: !!(data as any)?.live_dispatch_enabled,
    daily_whapi_cap: Number((data as any)?.daily_whapi_cap ?? 60),
    queue_a_wait_minutes: Number((data as any)?.queue_a_wait_minutes ?? 5),
    queue_a_silence_hours: Number((data as any)?.queue_a_silence_hours ?? 2),
    cooldown_hours: Number((data as any)?.cooldown_hours ?? 72),
    cold_min_age_hours: Number((data as any)?.cold_min_age_hours ?? 72),
    window_start_brt: String((data as any)?.window_start_brt ?? "09:00").slice(0, 8),
    window_end_brt: String((data as any)?.window_end_brt ?? "18:30").slice(0, 8),
    weekdays_only: (data as any)?.weekdays_only !== false,
    flow_variant: String((data as any)?.flow_variant ?? "F"),
    priority_queue: ((data as any)?.priority_queue ?? "A_then_B") as DailyReheatSettings["priority_queue"],
    pilot_consultant_ids: Array.isArray((data as any)?.pilot_consultant_ids)
      ? (data as any).pilot_consultant_ids.map(String)
      : [],
  };
}

function phoneTail(phone: string | null | undefined): string {
  const d = String(phone || "").replace(/\D/g, "");
  return d.slice(-4) || "????";
}

function baseGuards(c: any): string[] {
  const g: string[] = [];
  if (c.bot_paused) g.push("bot_paused");
  if (c.assigned_human_id) g.push("assigned_human");
  if (c.do_not_contact) g.push("do_not_contact");
  if (TERMINAL_STEPS.has(c.conversation_step || "")) g.push("terminal_step");
  if (c.capture_mode === "manual") g.push("capture_manual");
  return g;
}

async function planDailyReheat(
  supabase: SB,
  settings: DailyReheatSettings,
  opts: { cycleDate: string; limitScan?: number } = { cycleDate: cycleDateBRT() },
): Promise<{
  plans: CandidatePlan[];
  skippedGuards: number;
  skippedCap: number;
  scannedA: number;
  scannedB: number;
}> {
  const limitScan = opts.limitScan ?? 80;
  const now = Date.now();
  const waitMs = settings.queue_a_wait_minutes * 60_000;
  const coldAgeMs = settings.cold_min_age_hours * 3600_000;
  const cooldownMs = settings.cooldown_hours * 3600_000;
  const novoCutoff = new Date(now - waitMs).toISOString();
  const novoLookback = new Date(now - 24 * 3600_000).toISOString();
  const coldBefore = new Date(now - coldAgeMs).toISOString();
  const cooldownSince = new Date(now - cooldownMs).toISOString();

  let qA = supabase
    .from("customers")
    .select(
      "id, name, phone_whatsapp, consultant_id, created_at, welcome_sent_at, conversation_step, bot_paused, assigned_human_id, do_not_contact, capture_mode, customer_origin, last_bot_interaction_at",
    )
    .lte("created_at", novoCutoff)
    .gte("created_at", novoLookback)
    .is("welcome_sent_at", null)
    .eq("bot_paused", false)
    .is("assigned_human_id", null)
    .or("customer_origin.in.(whatsapp_lead,manual),customer_origin.is.null")
    .order("created_at", { ascending: true })
    .limit(limitScan);

  let qB = supabase
    .from("customers")
    .select(
      "id, name, phone_whatsapp, consultant_id, created_at, welcome_sent_at, conversation_step, bot_paused, assigned_human_id, do_not_contact, capture_mode, customer_origin, last_bot_interaction_at",
    )
    .lte("created_at", coldBefore)
    .eq("bot_paused", false)
    .is("assigned_human_id", null)
    .or("customer_origin.in.(whatsapp_lead,manual),customer_origin.is.null")
    .order("last_bot_interaction_at", { ascending: true, nullsFirst: true })
    .limit(limitScan);

  if (settings.pilot_consultant_ids.length > 0) {
    qA = qA.in("consultant_id", settings.pilot_consultant_ids);
    qB = qB.in("consultant_id", settings.pilot_consultant_ids);
  }

  const [{ data: rowsA }, { data: rowsB }] = await Promise.all([qA, qB]);


  const { data: existing } = await supabase
    .from("daily_reheat_queue")
    .select("customer_id")
    .eq("cycle_date", opts.cycleDate);
  const already = new Set((existing || []).map((r: any) => r.customer_id));


  const idsForCooldown = [
    ...new Set([
      ...(rowsA || []).map((r: any) => r.id),
      ...(rowsB || []).map((r: any) => r.id),
    ]),
  ];
  const recentTouch = new Set<string>();
  if (idsForCooldown.length > 0) {
    const { data: touches } = await supabase
      .from("proactive_touch_log")
      .select("customer_id")
      .in("customer_id", idsForCooldown.slice(0, 200))
      .gte("created_at", cooldownSince);
    for (const t of touches || []) recentTouch.add((t as any).customer_id);
  }


  const phones = [
    ...new Set(
      [...(rowsA || []), ...(rowsB || [])]
        .map((r: any) => String(r.phone_whatsapp || "").replace(/\D/g, ""))
        .filter((p) => p.length >= 10),
    ),
  ];
  const dncPhones = new Set<string>();
  if (phones.length > 0) {
    const { data: dnc } = await supabase
      .from("voice_dnc_list")
      .select("phone")
      .in("phone", phones.slice(0, 200));
    for (const d of dnc || []) {
      dncPhones.add(String((d as any).phone || "").replace(/\D/g, ""));
    }
  }

  let skippedGuards = 0;
  const rawPlans: CandidatePlan[] = [];

  const consider = (c: any, queue: "A" | "B") => {
    if (already.has(c.id)) {
      skippedGuards++;
      return;
    }
    const guards = baseGuards(c);
    const digits = String(c.phone_whatsapp || "").replace(/\D/g, "");
    if (dncPhones.has(digits)) guards.push("voice_dnc");
    if (recentTouch.has(c.id)) guards.push("proactive_cooldown");
    if (!c.phone_whatsapp) guards.push("no_phone");

    if (guards.length > 0) {
      skippedGuards++;
      return;
    }

    const q = queue as CycleQueue;
    const first = firstStep(q);
    rawPlans.push({
      customer_id: c.id,
      consultant_id: c.consultant_id,
      queue: q,
      step: first.id,
      phone_tail: phoneTail(c.phone_whatsapp),
      name: c.name,
      planned_actions: [...first.actions],
      would_consume_whapi: first.would_consume_whapi,
      would_call: first.would_call,
      would_sms: first.would_sms,
      reason:
        q === "A"
          ? `novo_wait_${settings.queue_a_wait_minutes}min`
          : `frio_age_${settings.cold_min_age_hours}h`,
      guards: [],
    });
  };

  for (const c of rowsA || []) consider(c, "A");

  const takenA = new Set(rawPlans.filter((p) => p.queue === "A").map((p) => p.customer_id));
  for (const c of rowsB || []) {
    if (takenA.has(c.id)) continue;
    consider(c, "B");
  }


  const order =
    settings.priority_queue === "B_then_A"
      ? [...rawPlans.filter((p) => p.queue === "B"), ...rawPlans.filter((p) => p.queue === "A")]
      : settings.priority_queue === "A_only"
        ? rawPlans.filter((p) => p.queue === "A")
        : settings.priority_queue === "B_only"
          ? rawPlans.filter((p) => p.queue === "B")
          : [...rawPlans.filter((p) => p.queue === "A"), ...rawPlans.filter((p) => p.queue === "B")];


  const { count: usedToday } = await supabase
    .from("daily_reheat_queue")
    .select("id", { count: "exact", head: true })
    .eq("cycle_date", opts.cycleDate)
    .in("status", ["planned", "claimed", "done"]);

  let slotsLeft = Math.max(0, settings.daily_whapi_cap - (usedToday ?? 0));
  const plans: CandidatePlan[] = [];
  let skippedCap = 0;

  for (const p of order) {
    if (!p.would_consume_whapi) {
      plans.push(p);
      continue;
    }
    if (slotsLeft <= 0) {
      skippedCap++;
      continue;
    }
    plans.push(p);
    slotsLeft--;
  }

  return {
    plans,
    skippedGuards,
    skippedCap,
    scannedA: (rowsA || []).length,
    scannedB: (rowsB || []).length,
  };
}

async function loadDueQueuePlans(
  supabase: SB,
  opts: { cycleDate: string; limit?: number } = { cycleDate: cycleDateBRT() },
): Promise<CandidatePlan[]> {
  const limit = opts.limit ?? 40;
  const nowIso = new Date().toISOString();
  const { data: rows } = await supabase
    .from("daily_reheat_queue")
    .select(
      "customer_id, consultant_id, queue, step, planned_actions, status, next_action_at",
    )
    .eq("cycle_date", opts.cycleDate)
    .in("status", ["planned", "claimed"])
    .lte("next_action_at", nowIso)
    .order("next_action_at", { ascending: true })
    .limit(limit);

  if (!rows?.length) return [];

  const ids = rows.map((r: any) => r.customer_id);
  const { data: custs } = await supabase
    .from("customers")
    .select("id, name, phone_whatsapp, do_not_contact, bot_paused, assigned_human_id")
    .in("id", ids);
  const byId = new Map((custs || []).map((c: any) => [c.id, c]));

  const plans: CandidatePlan[] = [];
  for (const r of rows as any[]) {
    const c = byId.get(r.customer_id);
    if (!c) continue;
    if (c.do_not_contact || c.bot_paused || c.assigned_human_id) {
      await supabase
        .from("daily_reheat_queue")
        .update({
          status: "skipped",
          skip_reason: c.do_not_contact
            ? "do_not_contact"
            : c.bot_paused
              ? "bot_paused"
              : "assigned_human",
          updated_at: new Date().toISOString(),
        })
        .eq("customer_id", r.customer_id)
        .eq("cycle_date", opts.cycleDate);
      continue;
    }

    const queue = (r.queue === "B" ? "B" : "A") as CycleQueue;
    const def = stepDef(queue, String(r.step || "")) || firstStep(queue);
    const actions =
      Array.isArray(r.planned_actions) && r.planned_actions.length > 0
        ? (r.planned_actions as PlannedAction[])
        : [...def.actions];

    plans.push({
      customer_id: r.customer_id,
      consultant_id: r.consultant_id,
      queue,
      step: def.id,
      phone_tail: phoneTail(c.phone_whatsapp),
      name: c.name,
      planned_actions: actions,
      would_consume_whapi: def.would_consume_whapi,
      would_call: def.would_call,
      would_sms: def.would_sms,
      reason: `due_step_${def.id}`,
      guards: [],
    });
  }
  return plans;
}

type SB__ared_automation_gate = any;

const cache = new Map<string, { value: boolean; expires: number }>();
const TTL_MS = 15_000;

async function isAutomationEnabled(
  supabase: SB__ared_automation_gate,
  key: string,
): Promise<boolean> {
  const now = Date.now();
  const hit = cache.get(key);
  if (hit && hit.expires > now) return hit.value;

  const { data, error } = await supabase
    .from("automation_toggles")
    .select("enabled")
    .eq("key", key)
    .maybeSingle();

  const value = !!(data as { enabled?: boolean } | null)?.enabled && !error;
  cache.set(key, { value, expires: now + TTL_MS });
  return value;
}

async function logSkipped(
  supabase: SB__ared_automation_gate,
  key: string,
  meta: Record<string, unknown> = {},
): Promise<void> {

  try {
    console.log(JSON.stringify({ level: "info", event: "automation_skipped_toggle_off", key, ...meta }));
  } catch {  }



  try {
    const { error } = await supabase.from("automation_skip_log").insert({ key, meta });
    if (error) console.warn(`[automation-gate] skip log falhou: ${error.message}`);
  } catch {

  }
}

type SB__ared_bot_global_flag = any;

let _cache: { enabled: boolean; t: number } | null = null;
const TTL_MS__ared_bot_global_flag = 5_000;

async function isBotGloballyEnabled(supabase: SB__ared_bot_global_flag): Promise<boolean> {
  if (_cache && Date.now() - _cache.t < TTL_MS__ared_bot_global_flag) return _cache.enabled;
  try {
    const { data } = await supabase
      .from("app_settings")
      .select("bot_global_enabled")
      .eq("id", "global")
      .maybeSingle();

    const enabled = data ? !!(data as any).bot_global_enabled : true;
    _cache = { enabled, t: Date.now() };
    return enabled;
  } catch {
    return true;
  }
}

function clearBotGlobalFlagCache() {
  _cache = null;
}

let _strictCache: { enabled: boolean; t: number } | null = null;

async function isResolverStrictMode(supabase: SB__ared_bot_global_flag): Promise<boolean> {
  if (_strictCache && Date.now() - _strictCache.t < TTL_MS__ared_bot_global_flag) return _strictCache.enabled;
  try {
    const { data } = await supabase
      .from("app_settings")
      .select("resolver_strict_mode")
      .eq("id", "global")
      .maybeSingle();
    const enabled = data ? !!(data as any).resolver_strict_mode : false;
    _strictCache = { enabled, t: Date.now() };
    return enabled;
  } catch {
    return false;
  }
}

function isQuietHourBRT(now: Date = new Date()): boolean {
  const fmt = new Intl.DateTimeFormat("en-GB", {
    timeZone: "America/Sao_Paulo",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).format(now);
  const [h, m] = fmt.split(":").map(Number);
  const minutes = h * 60 + m;
  const start = 21 * 60 + 30;
  const end = 8 * 60;
  return minutes >= start || minutes < end;
}

function nextQuietWindowEndISO(now: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  })
    .formatToParts(now)
    .reduce<Record<string, string>>((a, p) => ((a[p.type] = p.value), a), {});
  const hhmm = Number(parts.hour) * 60 + Number(parts.minute);
  let targetDate: string;
  if (hhmm < 8 * 60) {
    targetDate = `${parts.year}-${parts.month}-${parts.day}`;
  } else {
    const d = new Date(
      Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day) + 1),
    );
    targetDate = d.toISOString().slice(0, 10);
  }
  return new Date(`${targetDate}T08:00:00-03:00`).toISOString();
}

function logQuietSkip(fn: string, extra: Record<string, unknown> = {}): void {
  try {
    console.log(JSON.stringify({ level: "info", event: "quiet_hours_skip", function: fn, ...extra }));
  } catch {

  }
}

type CycleQueue = "A" | "B";

type CycleStepDef = {
  id: string;
  actions: PlannedAction[];

  next: string | null;

  delayMin: number;
  would_consume_whapi: boolean;
  would_call: boolean;
  would_sms: boolean;
};

const NOVO_CYCLE: CycleStepDef[] = [
  {
    id: "open",
    actions: ["open_attendance", "send_audio"],
    next: "flow",
    delayMin: 0,
    would_consume_whapi: true,
    would_call: false,
    would_sms: false,
  },
  {
    id: "flow",
    actions: ["start_flow"],
    next: "wait2h",
    delayMin: 0,
    would_consume_whapi: false,
    would_call: false,
    would_sms: false,
  },
  {
    id: "wait2h",
    actions: ["wait"],
    next: "call1",
    delayMin: 0,
    would_consume_whapi: false,
    would_call: false,
    would_sms: false,
  },
  {
    id: "call1",
    actions: ["call"],
    next: "retry",
    delayMin: 20,
    would_consume_whapi: false,
    would_call: true,
    would_sms: false,
  },
  {
    id: "retry",
    actions: ["call"],
    next: "sms",
    delayMin: 15,
    would_consume_whapi: false,
    would_call: true,
    would_sms: false,
  },
  {
    id: "sms",
    actions: ["sms"],
    next: "close",
    delayMin: 0,
    would_consume_whapi: false,
    would_call: false,
    would_sms: true,
  },
  {
    id: "close",
    actions: ["close_rating"],
    next: null,
    delayMin: 0,
    would_consume_whapi: true,
    would_call: false,
    would_sms: false,
  },
];

const FRIO_CYCLE: CycleStepDef[] = [
  {
    id: "call1",
    actions: ["call"],
    next: "open",
    delayMin: 0,
    would_consume_whapi: false,
    would_call: true,
    would_sms: false,
  },
  {
    id: "open",
    actions: ["open_attendance", "send_audio"],
    next: "retry",
    delayMin: 20,
    would_consume_whapi: true,
    would_call: false,
    would_sms: false,
  },
  {
    id: "retry",
    actions: ["call"],
    next: "sms",
    delayMin: 15,
    would_consume_whapi: false,
    would_call: true,
    would_sms: false,
  },
  {
    id: "sms",
    actions: ["sms"],
    next: "wait",
    delayMin: 0,
    would_consume_whapi: false,
    would_call: false,
    would_sms: true,
  },
  {
    id: "wait",
    actions: ["start_flow"],
    next: "close",
    delayMin: 0,
    would_consume_whapi: false,
    would_call: false,
    would_sms: false,
  },
  {
    id: "close",
    actions: ["close_rating"],
    next: null,
    delayMin: 0,
    would_consume_whapi: true,
    would_call: false,
    would_sms: false,
  },
];

function cycleFor(queue: CycleQueue): CycleStepDef[] {
  return queue === "A" ? NOVO_CYCLE : FRIO_CYCLE;
}

function stepDef(queue: CycleQueue, stepId: string): CycleStepDef | null {
  return cycleFor(queue).find((s) => s.id === stepId) ?? null;
}

function firstStep(queue: CycleQueue): CycleStepDef {
  return cycleFor(queue)[0];
}

function delayMinutesForTransition(
  queue: CycleQueue,
  fromStepId: string,
  toStepId: string | null,
  silenceHours: number,
): number {
  if (!toStepId) return 0;
  const from = stepDef(queue, fromStepId);
  if (!from) return 0;

  if (toStepId === "wait2h") {
    return Math.max(1, Math.round(silenceHours * 60));
  }

  if (fromStepId === "wait2h") return 0;
  return Math.max(0, from.delayMin);
}

type SB__aily_reheat_dispatch = any;

type CycleKit = {
  consultant_id: string;
  wa_open_text: string | null;
  wa_audio_mon_url: string | null;
  wa_audio_tue_url: string | null;
  wa_audio_wed_url: string | null;
  wa_audio_thu_url: string | null;
  wa_audio_fri_url: string | null;
  wa_audio_sat_url: string | null;
  voice_audio_clip_id: string | null;
  voice_audio_clip_id_retry: string | null;
  personalize_name: boolean;
  call_tts_fallback: string | null;
  sms_na_text: string | null;
  sms_retry_text: string | null;
  bina_notes: string | null;
  velip_audio_id?: string | null;
  velip_audio_id_retry?: string | null;
};

type DispatchGates = {
  toggleOn: boolean;
  settingsEnabled: boolean;
  liveDispatchEnabled: boolean;
  botGlobalEnabled: boolean;
};

function canLiveDispatch(gates: DispatchGates): boolean {
  return (
    gates.toggleOn &&
    gates.settingsEnabled &&
    gates.liveDispatchEnabled &&
    gates.botGlobalEnabled
  );
}

async function loadDispatchGates(
  supabase: SB__aily_reheat_dispatch,
  settings: DailyReheatSettings & { live_dispatch_enabled?: boolean },
): Promise<DispatchGates> {
  const [toggleOn, botGlobalEnabled] = await Promise.all([
    isAutomationEnabled(supabase, "daily_reheat"),
    isBotGloballyEnabled(supabase),
  ]);
  return {
    toggleOn,
    settingsEnabled: !!settings.enabled,
    liveDispatchEnabled: !!(settings as any).live_dispatch_enabled,
    botGlobalEnabled,
  };
}

async function loadCycleKit(supabase: SB__aily_reheat_dispatch, consultantId: string): Promise<CycleKit | null> {
  const { data } = await supabase
    .from("daily_reheat_kit")
    .select("*")
    .eq("consultant_id", consultantId)
    .maybeSingle();
  if (!data) return null;

  let velip_audio_id: string | null = null;
  let velip_audio_id_retry: string | null = null;
  const clipIds = [data.voice_audio_clip_id, data.voice_audio_clip_id_retry].filter(
    (id: string | null | undefined): id is string => !!id,
  );
  if (clipIds.length) {
    const { data: clips } = await supabase
      .from("voice_audio_clips")
      .select("id, velip_audio_id")
      .in("id", clipIds);
    const byId = new Map(
      (clips ?? []).map((c: { id: string; velip_audio_id: string | null }) => [
        c.id,
        c.velip_audio_id,
      ]),
    );
    if (data.voice_audio_clip_id) velip_audio_id = byId.get(data.voice_audio_clip_id) ?? null;
    if (data.voice_audio_clip_id_retry) {
      velip_audio_id_retry = byId.get(data.voice_audio_clip_id_retry) ?? null;
    }
  }

  return {
    ...data,
    personalize_name: !!data.personalize_name,
    voice_audio_clip_id_retry: data.voice_audio_clip_id_retry ?? null,
    velip_audio_id,
    velip_audio_id_retry,
  } as CycleKit;
}

function weekdayWaAudioUrl(kit: CycleKit, now = new Date()): string | null {
  const wd = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Sao_Paulo",
    weekday: "short",
  }).format(now);
  const map: Record<string, string | null | undefined> = {
    Mon: kit.wa_audio_mon_url,
    Tue: kit.wa_audio_tue_url,
    Wed: kit.wa_audio_wed_url,
    Thu: kit.wa_audio_thu_url,
    Fri: kit.wa_audio_fri_url,
    Sat: kit.wa_audio_sat_url,
    Sun: kit.wa_audio_sat_url,
  };
  return map[wd] || kit.wa_audio_mon_url || null;
}

function renderVars(
  text: string,
  vars: Record<string, string>,
): string {
  let out = text;
  for (const [k, v] of Object.entries(vars)) {
    out = out.replaceAll(`{{${k}}}`, v).replaceAll(`{{ ${k} }}`, v);
  }
  return out;
}

async function loadNames(supabase: SB__aily_reheat_dispatch, customerId: string, consultantId: string | null) {
  const { data: cust } = await supabase
    .from("customers")
    .select("id, name, phone_whatsapp, tracking_protocol, flow_variant")
    .eq("id", customerId)
    .maybeSingle();
  let consultor = "iGreen";
  if (consultantId) {
    const { data: c } = await supabase
      .from("consultants")
      .select("name, display_name")
      .eq("id", consultantId)
      .maybeSingle();
    consultor = (c as any)?.display_name || (c as any)?.name || consultor;
  }
  const nome = ((cust as any)?.name || "").split(" ")[0] || "tudo bem";
  return {
    cust,
    nome,
    consultor,
    protocolo: String((cust as any)?.tracking_protocol || ""),
  };
}

type ActionResult = { action: PlannedAction; ok: boolean; detail: string };

async function runOpenAttendance(
  supabase: SB__aily_reheat_dispatch,
  plan: CandidatePlan,
  kit: CycleKit | null,
  env: Record<string, string>,
): Promise<ActionResult> {
  const { nome, consultor, protocolo } = await loadNames(
    supabase,
    plan.customer_id,
    plan.consultant_id,
  );
  const raw =
    kit?.wa_open_text?.trim() ||
    `Oi {{nome}}, aqui é {{consultor}} da iGreen.\n\nProtocolo {{protocolo}} — vou te ajudar com a conta de luz.`;
  const text = renderVars(raw, { nome, consultor, protocolo });
  const audio = kit ? weekdayWaAudioUrl(kit) : null;

  const r = await sendWelcomeHeader(supabase, {
    customerId: plan.customer_id,
    consultantId: plan.consultant_id || undefined,
    env: env as any,
    customTemplate: { text, audio_url: audio, typing_delay_ms: 0 },
  });
  if (!r.ok && (r as any).skipped !== "already_sent") {
    return { action: "open_attendance", ok: false, detail: (r as any).code || "welcome_failed" };
  }
  return {
    action: "open_attendance",
    ok: true,
    detail: (r as any).skipped === "already_sent" ? "already_sent" : "opened",
  };
}

async function runSendAudio(
  supabase: SB__aily_reheat_dispatch,
  plan: CandidatePlan,
  kit: CycleKit | null,
  env: Record<string, string>,
): Promise<ActionResult> {
  const url = kit ? weekdayWaAudioUrl(kit) : null;
  if (!url) return { action: "send_audio", ok: true, detail: "no_audio_configured_skip" };

  const ch = await resolveChannelForCustomer(supabase, plan.customer_id, env as any);
  if ((ch as any).unavailable) {
    return { action: "send_audio", ok: false, detail: (ch as any).reason || "no_channel" };
  }

  const { data: cust } = await supabase
    .from("customers")
    .select("phone_whatsapp")
    .eq("id", plan.customer_id)
    .maybeSingle();
  const digits = String(cust?.phone_whatsapp || "").replace(/\D/g, "");
  if (digits.length < 12) return { action: "send_audio", ok: false, detail: "no_phone" };
  const jid = `${digits}@s.whatsapp.net`;

  const r = await (ch as any).adapter.sendMedia(
    jid,
    { kind: "audio", url, ptt: true } as any,
    {
      customerId: plan.customer_id,
      consultantId: plan.consultant_id || "",
      stepId: "daily_reheat:audio",
      idempotencyKey: `dreheat-audio:${plan.customer_id}:${Date.now()}`,
      supabase,
    } as any,
  );
  if (!(r as any)?.ok) {
    return { action: "send_audio", ok: false, detail: (r as any)?.detail || "send_failed" };
  }
  return { action: "send_audio", ok: true, detail: "audio_sent" };
}

async function runCall(
  supabase: SB__aily_reheat_dispatch,
  plan: CandidatePlan,
  kit: CycleKit | null,
): Promise<ActionResult> {
  if (!velipConfigured()) return { action: "call", ok: false, detail: "velip_not_configured" };
  const { cust, nome } = await loadNames(supabase, plan.customer_id, plan.consultant_id);
  if (!cust?.phone_whatsapp) return { action: "call", ok: false, detail: "no_phone" };
  const dest = toVelipBRDest(cust.phone_whatsapp);
  if (!dest) return { action: "call", ok: false, detail: "invalid_phone" };

  const ctid = toCtid(`dreheat_${plan.customer_id.slice(0, 8)}_${Date.now()}`);

  const isRetry = plan.step === "retry";
  const bodyClipId = isRetry
    ? (kit?.voice_audio_clip_id_retry || kit?.voice_audio_clip_id || null)
    : (kit?.voice_audio_clip_id || null);
  const bodyVelipId = isRetry
    ? (kit?.velip_audio_id_retry || kit?.velip_audio_id || null)
    : (kit?.velip_audio_id || null);
  const personalize = !!kit?.personalize_name;

  try {
    let r;
    if (bodyClipId && personalize) {
      const st = await resolvePersonalizedCallAudio(supabase, {
        consultantId: plan.consultant_id,
        bodyClipId,
        rawName: nome,
        fallbackToBody: true,
      });
      if (st.ok && st.velip_audio_id) {
        r = await playAudioFile({ to: dest, audioId: st.velip_audio_id, ctid });
      } else if (bodyVelipId) {
        r = await playAudioFile({ to: dest, audioId: bodyVelipId, ctid });
      } else {
        return { action: "call", ok: false, detail: "sofia_required_no_audio" };
      }
    } else if (bodyVelipId) {
      r = await playAudioFile({ to: dest, audioId: bodyVelipId, ctid });
    } else if (bodyClipId) {

      const st = await resolvePersonalizedCallAudio(supabase, {
        consultantId: plan.consultant_id,
        bodyClipId,
        rawName: personalize ? nome : null,
        fallbackToBody: true,
      });
      if (st.ok && st.velip_audio_id) {
        r = await playAudioFile({ to: dest, audioId: st.velip_audio_id, ctid });
      } else {
        return { action: "call", ok: false, detail: "sofia_required_no_audio" };
      }
    } else {
      return { action: "call", ok: false, detail: "sofia_required_no_clip" };
    }
    if (!r.ok) return { action: "call", ok: false, detail: `velip:${r.error || "fail"}` };
    return { action: "call", ok: true, detail: `call_placed:${r.cd_id ?? "?"}` };
  } catch (e) {
    return { action: "call", ok: false, detail: (e as Error).message };
  }
}

async function runSms(
  supabase: SB__aily_reheat_dispatch,
  plan: CandidatePlan,
  kit: CycleKit | null,
  which: "sms" | "retry" = "sms",
): Promise<ActionResult> {
  if (!velipConfigured()) return { action: "sms", ok: false, detail: "velip_not_configured" };
  const { cust, nome, consultor, protocolo } = await loadNames(
    supabase,
    plan.customer_id,
    plan.consultant_id,
  );
  if (!cust?.phone_whatsapp) return { action: "sms", ok: false, detail: "no_phone" };
  const dest = toVelipBRDest(cust.phone_whatsapp);
  if (!dest) return { action: "sms", ok: false, detail: "invalid_phone" };

  const raw =
    (which === "retry" ? kit?.sms_retry_text : kit?.sms_na_text)?.trim() ||
    kit?.sms_na_text?.trim() ||
    "";
  if (!raw) return { action: "sms", ok: true, detail: "no_sms_text_skip" };
  const message = renderVars(raw, { nome, consultor, protocolo });

  try {
    const r = await makeSMS({ to: dest, message });
    await supabase.from("voice_sms_log").insert({
      consultant_id: plan.consultant_id,
      phone: dest,
      message,
      velip_sms_id: r.cdls_id ?? null,
      status: r.ok ? "sent" : "failed",
      error: r.ok ? null : (r.error ?? "velip_error"),
      raw: r.raw ?? {},
      sent_at: r.ok ? new Date().toISOString() : null,
    });
    if (!r.ok) return { action: "sms", ok: false, detail: `velip:${r.error}` };
    return { action: "sms", ok: true, detail: `sms_sent:${r.cdls_id ?? "?"}` };
  } catch (e) {
    return { action: "sms", ok: false, detail: (e as Error).message };
  }
}

