async function dispatchCandidate(
  supabase: SB__aily_reheat_dispatch,
  plan: CandidatePlan,
  settings: DailyReheatSettings,
  kit: CycleKit | null,
  env: Record<string, string>,
): Promise<{ ok: boolean; results: ActionResult[] }> {
  const results: ActionResult[] = [];

  const contact = await assertCanContact(supabase, {
    customerId: plan.customer_id,
    channel: plan.would_call && !plan.would_consume_whapi ? "voice" : "whatsapp",
  });
  if (!contact.allowed) {
    return {
      ok: false,
      results: [{ action: "wait", ok: false, detail: `dnc:${contact.reason}` }],
    };
  }

  for (const action of plan.planned_actions) {
    if (action === "wait") {
      results.push({ action, ok: true, detail: "wait_noop" });
      continue;
    }
    let res: ActionResult;
    if (action === "open_attendance") res = await runOpenAttendance(supabase, plan, kit, env);
    else if (action === "send_audio") {

      const opened = results.find((r) => r.action === "open_attendance" && r.ok);
      if (opened && kit && weekdayWaAudioUrl(kit)) {
        res = { action: "send_audio", ok: true, detail: "bundled_in_open" };
      } else {
        res = await runSendAudio(supabase, plan, kit, env);
      }
    } else if (action === "start_flow") res = await runStartFlow(supabase, plan, settings);
    else if (action === "call") res = await runCall(supabase, plan, kit);
    else if (action === "sms") res = await runSms(supabase, plan, kit, "sms");
    else if (action === "close_rating") res = await runCloseRating(supabase, plan, env);
    else res = { action, ok: true, detail: "unknown_skip" };

    results.push(res);
    if (!res.ok && (action === "open_attendance" || action === "call")) break;
  }

  const ok = results.every((r) => r.ok);
  if (ok) {
    await recordProactiveTouch(supabase, plan.customer_id, "daily_reheat", {
      queue: plan.queue,
      step: plan.step,
      actions: results.map((r) => r.action),
    }).catch(() => {});
  }
  return { ok, results };
}

async function advanceQueueAfterSuccess(
  supabase: SB__aily_reheat_dispatch,
  plan: CandidatePlan,
  settings: DailyReheatSettings,
): Promise<{ nextDueNow: CandidatePlan | null }> {
  const cycleDate = cycleDateBRT();
  const queue = plan.queue as CycleQueue;
  const current = stepDef(queue, plan.step);
  if (!current) {
    await supabase
      .from("daily_reheat_queue")
      .update({ status: "done", updated_at: new Date().toISOString() })
      .eq("customer_id", plan.customer_id)
      .eq("cycle_date", cycleDate);
    return { nextDueNow: null };
  }

  const nextId = current.next;
  if (!nextId) {
    await supabase
      .from("daily_reheat_queue")
      .update({
        status: "done",
        step: current.id,
        planned_actions: [],
        updated_at: new Date().toISOString(),
      })
      .eq("customer_id", plan.customer_id)
      .eq("cycle_date", cycleDate);
    return { nextDueNow: null };
  }

  const next = stepDef(queue, nextId);
  if (!next) {
    await supabase
      .from("daily_reheat_queue")
      .update({ status: "done", updated_at: new Date().toISOString() })
      .eq("customer_id", plan.customer_id)
      .eq("cycle_date", cycleDate);
    return { nextDueNow: null };
  }

  const delayMin = delayMinutesForTransition(
    queue,
    current.id,
    nextId,
    settings.queue_a_silence_hours,
  );
  const nextAt = new Date(Date.now() + delayMin * 60_000).toISOString();

  await supabase
    .from("daily_reheat_queue")
    .update({
      status: "planned",
      step: next.id,
      planned_actions: next.actions,
      next_action_at: nextAt,
      skip_reason: null,
      updated_at: new Date().toISOString(),
    })
    .eq("customer_id", plan.customer_id)
    .eq("cycle_date", cycleDate);

  if (delayMin > 0) return { nextDueNow: null };

  return {
    nextDueNow: {
      ...plan,
      step: next.id,
      planned_actions: [...next.actions],
      would_consume_whapi: next.would_consume_whapi,
      would_call: next.would_call,
      would_sms: next.would_sms,
      reason: `chain_${next.id}`,
    },
  };
}

async function dispatchPlans(
  supabase: SB__aily_reheat_dispatch,
  plans: CandidatePlan[],
  settings: DailyReheatSettings,
  env: Record<string, string>,
): Promise<{
  dispatched: number;
  failed: number;
  details: Array<{ customer_id: string; ok: boolean; results: ActionResult[] }>;
}> {
  const kitCache = new Map<string, CycleKit | null>();
  let dispatched = 0;
  let failed = 0;
  const details: Array<{ customer_id: string; ok: boolean; results: ActionResult[] }> = [];
  const cycleDate = cycleDateBRT();

  for (const initial of plans) {
    let plan: CandidatePlan | null = initial;
    let hops = 0;
    while (plan && hops < 8) {
      hops++;
      const cid = plan.consultant_id || "";
      if (!kitCache.has(cid)) {
        kitCache.set(cid, cid ? await loadCycleKit(supabase, cid) : null);
      }
      const kit = kitCache.get(cid) ?? null;

      await supabase
        .from("daily_reheat_queue")
        .update({ status: "claimed", updated_at: new Date().toISOString() })
        .eq("customer_id", plan.customer_id)
        .eq("cycle_date", cycleDate)
        .in("status", ["planned", "claimed"]);

      const r = await dispatchCandidate(supabase, plan, settings, kit, env);
      details.push({ customer_id: plan.customer_id, ok: r.ok, results: r.results });
      if (!r.ok) {
        failed++;
        await supabase
          .from("daily_reheat_queue")
          .update({
            status: "blocked",
            skip_reason: r.results.find((x) => !x.ok)?.detail || "dispatch_failed",
            updated_at: new Date().toISOString(),
          })
          .eq("customer_id", plan.customer_id)
          .eq("cycle_date", cycleDate);
        break;
      }
      dispatched++;
      const { nextDueNow } = await advanceQueueAfterSuccess(supabase, plan, settings);
      plan = nextDueNow;
    }
  }

  return { dispatched, failed, details };
}

const VELIP_BASE = "https://vox.velip.com.br/api/v2";
const VELIP_IPS = new Set(["35.232.103.91", "35.184.30.236"]);

function velipConfigured(): boolean {
  return !!Deno.env.get("VELIP_API_TOKEN")?.trim();
}

function velipWebhookAuthConfigured(): boolean {
  return !!Deno.env.get("VELIP_WEBHOOK_AUTH")?.trim();
}

function getVelipToken(): string {
  return (Deno.env.get("VELIP_API_TOKEN") ?? "").trim();
}

function getVelipWebhookAuth(): string {
  return (Deno.env.get("VELIP_WEBHOOK_AUTH") ?? "").trim();
}

function velipWebhookAuthQuery(): string {
  const t = getVelipWebhookAuth();
  return t ? `&auth=${encodeURIComponent(t)}` : "";
}

function isVelipCallerIp(ip: string | null | undefined): boolean {
  if (!ip) return false;
  return VELIP_IPS.has(ip.trim());
}

function digitsOnly(raw: string | null | undefined): string {
  return String(raw ?? "").replace(/\D/g, "");
}

function toVelipBRDest(raw: string | null | undefined): string | null {
  let d = digitsOnly(raw);
  if (!d) return null;
  if (d.startsWith("55") && (d.length === 12 || d.length === 13)) return d;
  if (d.length === 10 || d.length === 11) return `55${d}`;
  if (d.length > 13) d = d.slice(-13);
  if (d.startsWith("55") && d.length >= 12) return d;
  if (d.length >= 10 && d.length <= 11) return `55${d}`;
  return null;
}

function toCtid(id: string): string {
  return String(id || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 15);
}

function velipHeaders(extra: Record<string, string> = {}): Record<string, string> {
  return {
    Authorization: `Bearer ${getVelipToken()}`,
    Accept: "application/json",
    ...extra,
  };
}

interface RawResp {
  ok: boolean;
  status_code?: number;
  status?: string;
  raw?: unknown;
  error?: string;
}

function velipEnvelope(json: Record<string, unknown>): Record<string, unknown> {
  const ret = json?.return;
  return ret && typeof ret === "object" ? (ret as Record<string, unknown>) : json;
}

function normalizeVelipStatus(raw: unknown): string | undefined {
  if (typeof raw === "string" && raw.trim()) return raw.trim();
  if (Array.isArray(raw) && raw.length > 0) {
    const first = raw[0];
    return typeof first === "string" ? first : String(first ?? "");
  }
  if (raw && typeof raw === "object") {
    const o = raw as Record<string, unknown>;
    const v = o["0"] ?? o.status ?? Object.values(o)[0];
    if (typeof v === "string" && v.trim()) return v.trim();
  }
  return undefined;
}

async function velipPost(
  path: string,
  form: URLSearchParams | FormData,
  timeoutMs = 20_000,
): Promise<RawResp> {
  const headers = velipHeaders();
  if (form instanceof URLSearchParams) {
    headers["Content-Type"] = "application/x-www-form-urlencoded; charset=UTF-8";
  }
  try {
    const res = await fetch(`${VELIP_BASE}${path}`, {
      method: "POST",
      headers,
      body: form,
      signal: AbortSignal.timeout(timeoutMs),
    });
    const text = await res.text();
    let json: Record<string, unknown> = {};
    try {
      json = text ? JSON.parse(text) : {};
    } catch {
      json = { _raw: text };
    }


    const env = velipEnvelope(json);
    const scRaw = env.status_code ?? json.status_code;
    const status_code = typeof scRaw === "number" ? scRaw : Number(scRaw ?? NaN);
    const status = normalizeVelipStatus(env.status) ?? normalizeVelipStatus(json.status);
    const ok = res.ok && (Number.isFinite(status_code) ? status_code === 0 : true);
    return {
      ok,
      status_code: Number.isFinite(status_code) ? status_code : undefined,
      status,
      raw: json,
      error: ok
        ? undefined
        : (status ?? `http_${res.status}`) +
          (Number.isFinite(status_code) ? `#${status_code}` : ""),
    };
  } catch (e) {
    return { ok: false, error: (e as Error)?.message || "network_error" };
  }
}

interface UserIDResp extends RawResp {
  saldo?: number | null;
}

async function getUserID(): Promise<UserIDResp> {
  const r = await velipPost("/GetUserID", new URLSearchParams(), 10_000);


  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const saldoRaw = env.saldo ?? env.balance ?? env.credit;
  const saldo = saldoRaw == null ? NaN : Number(saldoRaw);
  return { ...r, saldo: Number.isFinite(saldo) ? saldo : null };
}

interface UploadAudioResp extends RawResp {
  audio_id?: string;
}

async function uploadAudioFile(
  bytes: Uint8Array,
  name: string,
  contentType = "audio/mpeg",
): Promise<UploadAudioResp> {
  const fd = new FormData();


  const blob = new Blob([bytes as unknown as BlobPart], { type: contentType });
  const safeName = (name || "clipe").replace(/[^\w.-]+/g, "_").slice(0, 60) || "clipe";



  fd.append("audio", blob, `${safeName}.mp3`);
  fd.append("name", safeName);
  fd.append("name_up", `${safeName}.mp3`);
  fd.append("ttswrt", "1");
  const r = await velipPost("/CreateAudioFile", fd, 60_000);


  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const audio_id = String(
    env.cdw_file ?? env.audio_id ?? env.id ?? env.aid ?? env.audio ?? "",
  ) || undefined;
  return { ...r, audio_id };
}

interface AudioListItem {
  audio_id: string;
  name?: string;
  duration_sec?: number;
}

async function listAudios(): Promise<{ ok: boolean; items: AudioListItem[]; error?: string; raw?: unknown }> {
  const r = await velipPost("/GetAudiosList", new URLSearchParams(), 15_000);
  const raw = (r.raw ?? {}) as Record<string, unknown>;


  const arr = (raw.audios ?? raw.data ?? raw.list ?? []) as unknown[];
  const items: AudioListItem[] = [];
  if (Array.isArray(arr)) {
    for (const it of arr) {
      const row = it as Record<string, unknown>;
      const id = String(row.cdw_file ?? row.audio_id ?? row.id ?? "");
      if (!id) continue;
      items.push({
        audio_id: id,
        name: (row.cdw_name as string) ?? (row.name as string) ?? (row.nome as string) ?? undefined,
        duration_sec: Number(row.cdw_sec ?? row.duration_sec ?? row.duracao ?? NaN) || undefined,
      });
    }
  }
  return { ok: r.ok, items, error: r.error, raw };
}

interface MakeCallOpts {
  to: string;
  audioId?: string;
  ttsText?: string;

  voice?: string;
  ctid: string;
  timeLimitSec?: number;

  scheduledAt?: string;
  callerId?: string;

  free?: boolean;
}

interface MakeCallResult extends RawResp {
  cd_id?: string;
}

function baseCallForm(opts: MakeCallOpts): URLSearchParams {
  const form = new URLSearchParams();
  form.set("dest", opts.to);
  form.set("ctid", toCtid(opts.ctid));

  if (opts.timeLimitSec) form.set("timelimit", String(opts.timeLimitSec));
  if (opts.scheduledAt) form.set("block", opts.scheduledAt);
  const bina = opts.callerId ?? Deno.env.get("VELIP_CALLER_ID")?.trim();
  if (bina) form.set("callerid", bina);
  if (opts.free) form.set("free", "1");
  return form;
}

async function playAudioFile(opts: MakeCallOpts): Promise<MakeCallResult> {
  if (!opts.audioId) return { ok: false, error: "missing_audio_id" };
  return await makeTTSCall(opts);
}

async function makeTTSCall(opts: MakeCallOpts): Promise<MakeCallResult> {
  const form = baseCallForm(opts);
  if (opts.audioId) {



    const id = String(opts.audioId).trim();
    form.set("content", /^\d+$/.test(id) ? `tf${id}` : id);
  }
  if (opts.ttsText) {
    form.set("text", opts.ttsText);

    form.set("encoding", "UTF-8");
    if (opts.voice) form.set("voice", opts.voice);
  }
  const r = await velipPost("/MakeTTSCall", form);


  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const cd_id = String(env.cd_id ?? env.id ?? env.call_id ?? "") || undefined;
  return { ...r, cd_id: cd_id === "0" ? undefined : cd_id };
}

