type VelipOutcome =
  | "answered"
  | "no_answer"
  | "invalid_number"
  | "blocked"
  | "do_not_disturb"
  | "nonexistent"
  | "unknown";

function interpretStatus(cd_called_status: string | null | undefined): VelipOutcome {
  const s = String(cd_called_status || "").toUpperCase().trim();
  switch (s) {
    case "OK":
      return "answered";
    case "NA":
      return "no_answer";
    case "EK":
      return "invalid_number";
    case "CK":
      return "blocked";
    case "BK":
      return "do_not_disturb";
    case "IK":
      return "nonexistent";
    default:
      return "unknown";
  }
}

function isRetryable(outcome: VelipOutcome): boolean {
  return outcome === "no_answer";
}

function outcomeToTargetStatus(outcome: VelipOutcome):
  | "completed"
  | "no_answer"
  | "failed"
  | null
{
  switch (outcome) {
    case "answered":
      return "completed";
    case "no_answer":
      return "no_answer";
    case "invalid_number":
    case "blocked":
    case "do_not_disturb":
    case "nonexistent":
      return "failed";
    default:
      return null;
  }
}

function outcomeLabelPtBR(outcome: VelipOutcome): string {
  switch (outcome) {
    case "answered": return "Atendida";
    case "no_answer": return "Não atendeu";
    case "invalid_number": return "Número inválido";
    case "blocked": return "Bloqueio operadora";
    case "do_not_disturb": return "Não perturbe";
    case "nonexistent": return "Número inexistente";
    default: return "Desconhecido";
  }
}

function inCallWindow(cfg: {
  windowStart?: string;
  windowEnd?: string;
  weekdaysOnly?: boolean;
} | null): boolean {
  if (!cfg) return true;
  const now = new Date(Date.now() - 3 * 3600_000);
  if (cfg.weekdaysOnly) {
    const d = now.getUTCDay();
    if (d === 0 || d === 6) return false;
  }
  const start = cfg.windowStart || "09:00";
  const end = cfg.windowEnd || "18:00";
  const [sH, sM] = String(start).split(":").map(Number);
  const [eH, eM] = String(end).split(":").map(Number);
  const startMin = sH * 60 + (sM || 0);
  const endMin = eH * 60 + (eM || 0);
  const cur = now.getUTCHours() * 60 + now.getUTCMinutes();
  if (endMin < startMin) return cur >= startMin || cur <= endMin;
  return cur >= startMin && cur <= endMin;
}

type AdminClient = ReturnType<typeof createClient>;

const DEFAULT_VOICE = "EJV7H2baGt5ab95tOoSG";
const DEFAULT_MODEL = "eleven_multilingual_v2";

function normalizeCallName(input: string): string {
  return (input || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_|_$/g, "");
}

function firstNameFrom(raw: string | null | undefined): string {
  const n = String(raw || "").trim();
  if (!n) return "";
  return n.split(/\s+/)[0] || "";
}

function concatMp3Bytes(parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((s, p) => s + p.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.length;
  }
  return out;
}

async function stripId3(bytes: Uint8Array): Promise<Uint8Array> {
  if (bytes.length < 10) return bytes;
  if (bytes[0] !== 0x49 || bytes[1] !== 0x44 || bytes[2] !== 0x33) return bytes;
  const size = (bytes[6] << 21) | (bytes[7] << 14) | (bytes[8] << 7) | bytes[9];
  const total = 10 + size;
  if (total >= bytes.length) return bytes;
  return bytes.slice(total);
}

async function concatMp3Parts(parts: Uint8Array[]): Promise<Uint8Array> {
  if (parts.length === 0) return new Uint8Array();
  if (parts.length === 1) return parts[0];
  const cleaned: Uint8Array[] = [parts[0]];
  for (let i = 1; i < parts.length; i++) cleaned.push(await stripId3(parts[i]));
  return concatMp3Bytes(cleaned);
}

function voiceSettingsForModel(modelId: string): Record<string, unknown> {
  if (modelId === "eleven_v3") {
    return {
      stability: 0.5,
      similarity_boost: 0.75,
      style: 0.0,
      use_speaker_boost: true,
      speed: 1.0,
    };
  }
  return {
    stability: 0.9,
    similarity_boost: 1.0,
    style: 0.45,
    use_speaker_boost: true,
    speed: 1.0,
  };
}

async function synthesizeIntroMp3(opts: {
  displayName: string;
  voiceId: string;
  modelId: string;
}): Promise<Uint8Array> {
  const key = (Deno.env.get("ELEVENLABS_API_KEY") || "").trim();
  if (!key) throw new Error("ELEVENLABS_API_KEY_missing");
  const text = `Olá, ${opts.displayName}.`;
  const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${opts.voiceId}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "xi-api-key": key,
    },
    body: JSON.stringify({
      text,
      model_id: opts.modelId,
      voice_settings: voiceSettingsForModel(opts.modelId),
    }),
    signal: AbortSignal.timeout(60_000),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => null);
    const msg = err?.detail?.message || err?.message || `elevenlabs_${res.status}`;
    throw new Error(msg);
  }
  return new Uint8Array(await res.arrayBuffer());
}

interface StitchResult {
  ok: boolean;
  velip_audio_id?: string;
  cached?: boolean;
  fallback_body?: boolean;
  error?: string;
  render_id?: string;
}

async function resolvePersonalizedCallAudio(
  admin: AdminClient,
  opts: {
    consultantId: string;
    bodyClipId: string;
    rawName: string | null | undefined;

    fallbackToBody?: boolean;
  },
): Promise<StitchResult> {
  const fallback = opts.fallbackToBody !== false;
  const display = firstNameFrom(opts.rawName);
  const nameNorm = normalizeCallName(display);

  const { data: clip } = await admin
    .from("voice_audio_clips")
    .select("id, audio_url, name, velip_audio_id, voice_id, model_id, consultant_id")
    .eq("id", opts.bodyClipId)
    .eq("consultant_id", opts.consultantId)
    .maybeSingle();

  if (!clip?.audio_url) return { ok: false, error: "body_clip_not_found" };

  const voiceId = String(clip.voice_id || DEFAULT_VOICE);
  const modelId = String(clip.model_id || DEFAULT_MODEL);
  const bodyVelip = clip.velip_audio_id ? String(clip.velip_audio_id) : null;


  if (!display || !nameNorm) {
    if (bodyVelip) return { ok: true, velip_audio_id: bodyVelip, fallback_body: true, cached: true };
    return { ok: false, error: "no_name_and_no_body_velip" };
  }

  const { data: existing } = await admin
    .from("voice_call_renders")
    .select("id, velip_audio_id")
    .eq("body_clip_id", opts.bodyClipId)
    .eq("name_normalized", nameNorm)
    .eq("voice_id", voiceId)
    .eq("model_id", modelId)
    .maybeSingle();

  if (existing?.velip_audio_id) {
    return {
      ok: true,
      velip_audio_id: existing.velip_audio_id,
      cached: true,
      render_id: existing.id,
    };
  }

  try {
    const bodyRes = await fetch(clip.audio_url, { signal: AbortSignal.timeout(45_000) });
    if (!bodyRes.ok) throw new Error(`body_download_${bodyRes.status}`);
    const bodyBytes = new Uint8Array(await bodyRes.arrayBuffer());

    const introBytes = await synthesizeIntroMp3({
      displayName: display,
      voiceId,
      modelId,
    });

    const merged = await concatMp3Parts([introBytes, bodyBytes]);
    const slug = `call-${opts.bodyClipId.slice(0, 8)}-${nameNorm}`.slice(0, 60);
    const up = await uploadAudioFile(merged, slug, "audio/mpeg");
    if (!up.ok || !up.audio_id) throw new Error(up.error || "velip_upload_failed");

    const { data: upserted, error: upErr } = await admin
      .from("voice_call_renders")
      .upsert(
        {
          consultant_id: opts.consultantId,
          body_clip_id: opts.bodyClipId,
          name_normalized: nameNorm,
          display_name: display,
          voice_id: voiceId,
          model_id: modelId,
          velip_audio_id: up.audio_id,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "body_clip_id,name_normalized,voice_id,model_id" },
      )
      .select("id, velip_audio_id")
      .maybeSingle();

    if (upErr) console.warn("[call-stitch] upsert warn:", upErr.message);

    return {
      ok: true,
      velip_audio_id: up.audio_id,
      cached: false,
      render_id: upserted?.id,
    };
  } catch (e) {
    const msg = (e as Error)?.message || "stitch_failed";
    if (fallback && bodyVelip) {
      return { ok: true, velip_audio_id: bodyVelip, fallback_body: true, error: msg };
    }
    return { ok: false, error: msg };
  }
}

async function ensureBodyClipOnVelip(
  admin: AdminClient,
  clipId: string,
  consultantId: string,
): Promise<{ ok: true; audio_id: string } | { ok: false; error: string }> {
  const { data: clip } = await admin
    .from("voice_audio_clips")
    .select("id, audio_url, name, velip_audio_id")
    .eq("id", clipId)
    .eq("consultant_id", consultantId)
    .maybeSingle();
  if (!clip?.audio_url) return { ok: false, error: "clip_not_found" };
  if (clip.velip_audio_id) return { ok: true, audio_id: clip.velip_audio_id };
  try {
    const r = await fetch(clip.audio_url, { signal: AbortSignal.timeout(45_000) });
    if (!r.ok) return { ok: false, error: `download_${r.status}` };
    const bytes = new Uint8Array(await r.arrayBuffer());
    const up = await uploadAudioFile(bytes, clip.name || `clip_${clipId}`);
    if (!up.ok || !up.audio_id) return { ok: false, error: up.error || "velip_upload_failed" };
    await admin
      .from("voice_audio_clips")
      .update({ velip_audio_id: up.audio_id, velip_uploaded_at: new Date().toISOString() })
      .eq("id", clipId);
    return { ok: true, audio_id: up.audio_id };
  } catch (e) {
    return { ok: false, error: (e as Error).message || "upload_error" };
  }
}

type ContactChannel = "whatsapp" | "voice" | "sms" | "reheat" | "bulk" | "any";

interface ContactSuppressionInput {
  customerId?: string | null;
  phone?: string | null;
  consultantId?: string | null;
  channel?: ContactChannel;
}

interface ContactSuppressionResult {
  allowed: boolean;
  reason: string | null;
  doNotContact: boolean;
  voiceDnc: boolean;
}

function digitsOnly___contact_suppression(phone: string | null | undefined): string {
  return String(phone || "").replace(/\D/g, "");
}

function phonesMatch(a: string, b: string): boolean {
  if (!a || !b) return false;
  if (a === b) return true;
  return a.endsWith(b) || b.endsWith(a);
}

async function assertCanContact(
  supabase: SupabaseClient,
  input: ContactSuppressionInput,
): Promise<ContactSuppressionResult> {
  const channel = input.channel ?? "any";
  const phoneDigits = digitsOnly___contact_suppression(input.phone);
  let doNotContact = false;
  let voiceDnc = false;
  let consultantId = input.consultantId ?? null;

  try {
    if (input.customerId) {
      const { data, error } = await supabase
        .from("customers")
        .select("id, do_not_contact, phone_whatsapp, consultant_id")
        .eq("id", input.customerId)
        .maybeSingle();

      if (error) {
        console.warn("[contact-suppression] customer lookup failed:", error.message);
        return { allowed: false, reason: "lookup_error", doNotContact: true, voiceDnc: false };
      }
      if (!data) {
        return { allowed: false, reason: "customer_not_found", doNotContact: false, voiceDnc: false };
      }
      doNotContact = !!(data as { do_not_contact?: boolean }).do_not_contact;
      consultantId = consultantId || (data as { consultant_id?: string }).consultant_id || null;
      if (!phoneDigits) {
        const wa = digitsOnly___contact_suppression((data as { phone_whatsapp?: string }).phone_whatsapp);
        if (wa) {

          (input as { phone?: string }).phone = wa;
        }
      }
    }

    if (doNotContact) {
      return {
        allowed: false,
        reason: "do_not_contact",
        doNotContact: true,
        voiceDnc: false,
      };
    }


    const phoneForLookup = digitsOnly___contact_suppression(input.phone) || phoneDigits;
    if (!input.customerId && phoneForLookup.length >= 10) {
      const tail = phoneForLookup.slice(-11);
      let q = supabase
        .from("customers")
        .select("id, do_not_contact, phone_whatsapp, consultant_id")
        .eq("do_not_contact", true)
        .ilike("phone_whatsapp", `%${tail}`)
        .limit(10);
      if (consultantId) q = q.eq("consultant_id", consultantId);
      const { data: dncRowsByPhone, error: phoneLookupErr } = await q;
      if (phoneLookupErr) {
        console.warn("[contact-suppression] phone DNC lookup failed:", phoneLookupErr.message);
        return { allowed: false, reason: "lookup_error", doNotContact: true, voiceDnc: false };
      }
      const hit = (dncRowsByPhone ?? []).some((r: { phone_whatsapp?: string }) => {
        const d = digitsOnly___contact_suppression(r.phone_whatsapp);
        return phonesMatch(phoneForLookup, d);
      });
      if (hit) {
        return {
          allowed: false,
          reason: "do_not_contact",
          doNotContact: true,
          voiceDnc: false,
        };
      }
    }

    const checkVoiceDnc = channel === "voice" || channel === "sms" || channel === "reheat" || channel === "any";
    const phoneForDnc = digitsOnly___contact_suppression(input.phone) || phoneDigits;

    if (checkVoiceDnc && consultantId && phoneForDnc) {
      const { data: dncRows, error: voiceDncErr } = await supabase
        .from("voice_dnc_list")
        .select("phone")
        .eq("consultant_id", consultantId);

      if (voiceDncErr) {
        console.warn("[contact-suppression] voice_dnc lookup failed:", voiceDncErr.message);
        return { allowed: false, reason: "lookup_error", doNotContact: false, voiceDnc: true };
      }

      const blocked = (dncRows ?? []).map((r: { phone: string }) => digitsOnly___contact_suppression(r.phone)).filter(Boolean);
      voiceDnc = blocked.some((b) => phonesMatch(phoneForDnc, b));
      if (voiceDnc) {
        return {
          allowed: false,
          reason: "voice_dnc",
          doNotContact: false,
          voiceDnc: true,
        };
      }
    }

    return { allowed: true, reason: null, doNotContact: false, voiceDnc: false };
  } catch (e) {
    console.warn("[contact-suppression] unexpected:", (e as Error)?.message);

    return { allowed: false, reason: "exception", doNotContact: true, voiceDnc: false };
  }
}

async function applyCustomerSuppression(
  supabase: SupabaseClient,
  params: {
    customerId: string;
    consultantId: string;
    phone: string;
    reason?: string;
    channel?: string;
    actorId?: string | null;
    notes?: string | null;
  },
): Promise<{ ok: boolean; error?: string }> {
  const reason = params.reason || "complaint";
  const phone = digitsOnly___contact_suppression(params.phone);
  const now = new Date().toISOString();

  const { error: custErr } = await supabase
    .from("customers")
    .update({
      do_not_contact: true,
      bot_paused: true,
      bot_paused_reason: reason === "complaint" ? "complaint" : "opt_out",
      bot_paused_at: now,
      bot_force_enabled: false,
      attendance_rating_requested_at: null,
      conversation_step: "atendimento_finalizado",
    })
    .eq("id", params.customerId);

  if (custErr) return { ok: false, error: custErr.message };

  if (phone) {
    await supabase.from("voice_dnc_list").upsert(
      {
        consultant_id: params.consultantId,
        phone,
        reason,
        source: "admin_ui",
      },
      { onConflict: "consultant_id,phone" },
    );

    await supabase
      .from("captured_leads")
      .update({ status: "discarded" })
      .eq("consultant_id", params.consultantId)
      .or(`customer_id.eq.${params.customerId},phone.eq.${phone}`);
  }

  await supabase.from("contact_suppression_log").insert({
    customer_id: params.customerId,
    consultant_id: params.consultantId,
    phone: phone || params.phone || "",
    reason,
    channel: params.channel || "admin_ui",
    actor_id: params.actorId ?? null,
    notes: params.notes ?? null,
  });

  return { ok: true };
}

type SB__tention_orchestrator = any;

type RetentionSettings = {
  speed_to_lead_minutes: number;
  orchestrator_cooldown_hours: number;
  priority_order: string[];
  portal_abandon_hours: number;
  call_answered_pause_hours: number;
};

const DEFAULTS: RetentionSettings = {
  speed_to_lead_minutes: 5,
  orchestrator_cooldown_hours: 6,
  priority_order: [
    "process_followups",
    "bot_stuck_recovery",
    "faq_reengagement_nudge",
    "bot_followup_checker",
    "cadence_engine",
    "reactivation_cron",
    "portal_abandon_sequence",
  ],
  portal_abandon_hours: 2,
  call_answered_pause_hours: 24,
};

let settingsCache: { value: RetentionSettings; expires: number } | null = null;
const SETTINGS_TTL_MS = 30_000;

async function loadRetentionSettings(supabase: SB__tention_orchestrator): Promise<RetentionSettings> {
  const now = Date.now();
  if (settingsCache && settingsCache.expires > now) return settingsCache.value;

  const { data } = await supabase
    .from("retention_settings")
    .select("*")
    .eq("id", "global")
    .maybeSingle();

  const row = data as Partial<RetentionSettings> | null;
  const priority = Array.isArray(row?.priority_order)
    ? (row!.priority_order as string[])
    : DEFAULTS.priority_order;

  const value: RetentionSettings = {
    speed_to_lead_minutes: Number(row?.speed_to_lead_minutes) || DEFAULTS.speed_to_lead_minutes,
    orchestrator_cooldown_hours: Number(row?.orchestrator_cooldown_hours) || DEFAULTS.orchestrator_cooldown_hours,
    priority_order: priority.length ? priority : DEFAULTS.priority_order,
    portal_abandon_hours: Number(row?.portal_abandon_hours) || DEFAULTS.portal_abandon_hours,
    call_answered_pause_hours: Number(row?.call_answered_pause_hours) || DEFAULTS.call_answered_pause_hours,
  };
  settingsCache = { value, expires: now + SETTINGS_TTL_MS };
  return value;
}

function priorityIndex(order: string[], key: string): number {
  const i = order.indexOf(key);
  return i >= 0 ? i : 999;
}

async function canProactiveTouch(
  supabase: SB__tention_orchestrator,
  customerId: string,
  sourceKey: string,
): Promise<{ allowed: boolean; reason?: string; blockedBy?: string }> {
  if (!(await isAutomationEnabled(supabase, "retention_orchestrator"))) {
    return { allowed: true, reason: "orchestrator_off" };
  }

  const settings = await loadRetentionSettings(supabase);
  const since = new Date(
    Date.now() - settings.orchestrator_cooldown_hours * 3600_000,
  ).toISOString();

  const { data: recent } = await supabase
    .from("proactive_touch_log")
    .select("source_key, created_at")
    .eq("customer_id", customerId)
    .gte("created_at", since)
    .order("created_at", { ascending: false })
    .limit(5);

  const rows = (recent || []) as { source_key: string; created_at: string }[];
  if (rows.length === 0) return { allowed: true };

  const myPri = priorityIndex(settings.priority_order, sourceKey);
  for (const r of rows) {
    if (r.source_key === sourceKey) continue;
    const otherPri = priorityIndex(settings.priority_order, r.source_key);
    if (otherPri <= myPri) {
      return {
        allowed: false,
        reason: "blocked_by_higher_or_equal_priority",
        blockedBy: r.source_key,
      };
    }
  }
  return { allowed: true };
}

async function recordProactiveTouch(
  supabase: SB__tention_orchestrator,
  customerId: string,
  sourceKey: string,
  meta: Record<string, unknown> = {},
): Promise<void> {
  try {
    await supabase.from("proactive_touch_log").insert({
      customer_id: customerId,
      source_key: sourceKey,
      meta,
    });
  } catch (err) {
    console.warn("[retention-orchestrator] recordProactiveTouch failed", err);
  }
}

async function gateProactiveTouch(
  supabase: SB__tention_orchestrator,
  customerId: string,
  sourceKey: string,
): Promise<boolean> {
  const r = await canProactiveTouch(supabase, customerId, sourceKey);
  if (!r.allowed) {
    await logSkipped(supabase, "retention_orchestrator", {
      customer_id: customerId,
      source: sourceKey,
      blocked_by: r.blockedBy,
      reason: r.reason,
    });
    return false;
  }
  return true;
}

function decideProactiveTouchPure(
  settings: RetentionSettings,
  orchestratorEnabled: boolean,
  recentSources: string[],
  sourceKey: string,
): { allowed: boolean; blockedBy?: string } {
  if (!orchestratorEnabled) return { allowed: true };
  if (recentSources.length === 0) return { allowed: true };
  const myPri = priorityIndex(settings.priority_order, sourceKey);
  for (const other of recentSources) {
    if (other === sourceKey) continue;
    if (priorityIndex(settings.priority_order, other) <= myPri) {
      return { allowed: false, blockedBy: other };
    }
  }
  return { allowed: true };
}

