function normalizeAttendanceStep(raw: string | null | undefined): string {
  return String(raw || "")
    .replace(/^flow:/, "")
    .replace(/^passo_/, "");
}

function isAwaitingAttendanceRating(customer: {
  conversation_step?: string | null;
  attendance_rating?: number | null;
  attendance_rating_requested_at?: string | null;
}): boolean {
  if (customer.attendance_rating != null) return false;
  const step = normalizeAttendanceStep(customer.conversation_step);
  if (step === ATTENDANCE_RATING_STEP) return true;
  return !!customer.attendance_rating_requested_at;
}

function isAttendanceDone(customer: {
  conversation_step?: string | null;
  attendance_rating?: number | null;
}): boolean {
  if (customer.attendance_rating != null) return true;
  return normalizeAttendanceStep(customer.conversation_step) === ATTENDANCE_DONE_STEP;
}

function isAttendanceTerminalStep(
  conversationStep: string | null | undefined,
): boolean {
  return ATTENDANCE_TERMINAL_STEPS.has(normalizeAttendanceStep(conversationStep));
}

interface AttendanceRatingInterceptArgs {
  supabase: SB__ared_attendance_flow;
  customer: {
    id: string;
    consultant_id?: string | null;
    conversation_step?: string | null;
    attendance_rating?: number | null;
    attendance_rating_requested_at?: string | null;
    do_not_contact?: boolean | null;
  };
  remoteJid: string;
  messageText?: string | null;
  buttonId?: string | null;

  isMedia?: boolean;
  mediaKind?: "document" | "image" | "audio" | "video" | "file" | null;

  skipInboundLog?: boolean;
  sendText: (jid: string, text: string) => Promise<boolean>;
}

async function tryInterceptAttendanceRating(
  args: AttendanceRatingInterceptArgs,
): Promise<{ intercepted: boolean; rating?: number; invalid?: boolean; media?: boolean }> {
  if (!isAwaitingAttendanceRating(args.customer)) {
    return { intercepted: false };
  }


  let doNotContact = !!args.customer.do_not_contact;
  if (!doNotContact) {
    const { data: row } = await args.supabase
      .from("customers")
      .select("do_not_contact")
      .eq("id", args.customer.id)
      .maybeSingle();
    doNotContact = !!(row as { do_not_contact?: boolean } | null)?.do_not_contact;
  }
  if (doNotContact) {
    const inboundText = String(args.messageText || args.buttonId || "").slice(0, 200);
    if (!args.skipInboundLog && inboundText) {
      await args.supabase.from("conversations").insert({
        customer_id: args.customer.id,
        message_direction: "inbound",
        message_text: inboundText,
        message_type: "text",
        conversation_step: ATTENDANCE_DONE_STEP,
      }).then(() => {}, () => {});
    }
    const now = new Date().toISOString();
    await args.supabase.from("customers").update({
      conversation_step: ATTENDANCE_DONE_STEP,
      bot_paused: true,
      bot_paused_reason: "opt_out",
      bot_paused_at: now,
      bot_force_enabled: false,
      updated_at: now,
    }).eq("id", args.customer.id).then(() => {}, () => {});
    return { intercepted: true };
  }

  const rating = parseAttendanceRating({
    messageText: args.messageText,
    buttonId: args.buttonId,
  });

  const inboundText = String(args.messageText || args.buttonId || "").slice(0, 200);
  const isMediaOnly = !!args.isMedia && !rating;


  if (isMediaOnly) {
    const kind = args.mediaKind || "file";
    const label = kind === "document" ? "[documento/pdf]"
      : kind === "image" ? "[imagem]"
      : kind === "audio" ? "[áudio]"
      : kind === "video" ? "[vídeo]"
      : "[arquivo]";
    if (!args.skipInboundLog) {
      await args.supabase.from("conversations").insert({
        customer_id: args.customer.id,
        message_direction: "inbound",
        message_text: inboundText || label,
        message_type: kind === "document" ? "document" : (kind === "image" ? "image" : "text"),
        conversation_step: ATTENDANCE_RATING_STEP,
      }).then(() => {}, () => {});
    }
    const hint = await resolveAttendanceTpl(
      args.supabase,
      args.customer.consultant_id || null,
      "attendance_rating_media_hint",
      buildAttendanceRatingMediaHintText(),
    );
    try {
      await args.sendText(args.remoteJid, hint);
      await args.supabase.from("conversations").insert({
        customer_id: args.customer.id,
        message_direction: "outbound",
        message_text: hint,
        message_type: "text",
        conversation_step: ATTENDANCE_RATING_STEP,
      }).then(() => {}, () => {});
    } catch (_) {  }
    await args.supabase.from("customers").update({
      conversation_step: ATTENDANCE_RATING_STEP,
      bot_paused: false,
      bot_paused_reason: null,
      bot_paused_until: null,
      updated_at: new Date().toISOString(),
    }).eq("id", args.customer.id).then(() => {}, () => {});
    return { intercepted: true, invalid: true, media: true };
  }


  if (!rating) {
    if (!args.skipInboundLog && inboundText) {
      await args.supabase.from("conversations").insert({
        customer_id: args.customer.id,
        message_direction: "inbound",
        message_text: inboundText,
        message_type: "text",
        conversation_step: ATTENDANCE_RATING_STEP,
      }).then(() => {}, () => {});
    }
    const retry = await resolveAttendanceTpl(
      args.supabase,
      args.customer.consultant_id || null,
      "attendance_rating_retry",
      buildAttendanceRatingRetryText(),
    );
    try {
      await args.sendText(args.remoteJid, retry);
      await args.supabase.from("conversations").insert({
        customer_id: args.customer.id,
        message_direction: "outbound",
        message_text: retry,
        message_type: "text",
        conversation_step: ATTENDANCE_RATING_STEP,
      }).then(() => {}, () => {});
    } catch (_) {  }

    await args.supabase.from("customers").update({
      conversation_step: ATTENDANCE_RATING_STEP,
      updated_at: new Date().toISOString(),
    }).eq("id", args.customer.id).then(() => {}, () => {});
    return { intercepted: true, invalid: true };
  }

  if (!args.skipInboundLog) {
    await args.supabase.from("conversations").insert({
      customer_id: args.customer.id,
      message_direction: "inbound",
      message_text: inboundText || String(rating),
      message_type: "text",
      conversation_step: ATTENDANCE_RATING_STEP,
    }).then(() => {}, () => {});
  }

  const now = new Date().toISOString();
  const { error: saveErr } = await args.supabase
    .from("customers")
    .update({
      attendance_rating: rating,
      attendance_rating_at: now,
      conversation_step: ATTENDANCE_DONE_STEP,
      bot_paused: true,
      bot_paused_reason: "attendance_rated",
      bot_paused_at: now,
      bot_paused_until: null,
      updated_at: now,
    })
    .eq("id", args.customer.id);

  if (saveErr) {
    console.error("[attendance-rating] falha ao salvar nota:", saveErr.message);

  }

  const thanks = await resolveAttendanceTpl(
    args.supabase,
    args.customer.consultant_id || null,
    "attendance_rating_thanks",
    buildAttendanceThanksText(rating),
    { nota: rating },
  );
  try {
    await args.sendText(args.remoteJid, thanks);
    await args.supabase.from("conversations").insert({
      customer_id: args.customer.id,
      message_direction: "outbound",
      message_text: thanks,
      message_type: "text",
      conversation_step: ATTENDANCE_DONE_STEP,
    }).then(() => {}, () => {});
  } catch (e) {
    console.error("[attendance-rating] falha ao enviar thanks:", (e as Error)?.message);
  }

  return { intercepted: true, rating };
}

interface ChannelEnv {
  evolutionUrl: string | undefined;
  evolutionKey: string | undefined;
  whapiToken: string;
}

interface ResolvedChannel {
  kind: "evolution" | "whapi";
  instanceName: string;
  adapter: ChannelAdapter;
}

async function resolveChannel(
  supabase: any,
  consultantId: string,
  env: ChannelEnv,
): Promise<ResolvedChannel | null> {
  const { data: instance } = await supabase
    .from("whatsapp_instances")
    .select("instance_name")
    .eq("consultant_id", consultantId)
    .limit(1)
    .maybeSingle();

  if (instance?.instance_name && env.evolutionUrl && env.evolutionKey) {
    const adapter = getAdapter({
      kind: "evolution",
      input: {
        apiUrl: env.evolutionUrl,
        apiKey: env.evolutionKey,
        instanceName: instance.instance_name,
      },
    });
    return { kind: "evolution", instanceName: instance.instance_name, adapter };
  }

  if (env.whapiToken) {
    const adapter = getAdapter({
      kind: "whapi",
      input: { apiToken: env.whapiToken, instanceName: "whapi-superadmin" },
    });
    return { kind: "whapi", instanceName: "whapi-superadmin", adapter };
  }

  return null;
}

type ChannelUnavailableReason =
  | "no_origin_recorded"
  | "instance_not_found"
  | "instance_offline"
  | "instance_locked"
  | "manual_review_required"
  | "missing_credentials";

interface UnavailableChannel {
  unavailable: true;
  reason: ChannelUnavailableReason;
  detail: string;
  instanceName: string | null;
  kind: "evolution" | "whapi" | null;
}

const HEALTHY_STATUSES = new Set(["connected", "online", "open"]);

async function resolveChannelForCustomer(
  supabase: any,
  customerId: string,
  env: ChannelEnv,
): Promise<ResolvedChannel | UnavailableChannel> {
  const { data: c } = await supabase
    .from("customers")
    .select("origin_channel, origin_instance_name, consultant_id")
    .eq("id", customerId)
    .maybeSingle();

  const kind = (c?.origin_channel as "evolution" | "whapi" | null) || null;
  const instanceName = (c?.origin_instance_name as string | null) || null;

  if (!kind || !instanceName) {
    return {
      unavailable: true, reason: "no_origin_recorded",
      detail: "customer sem origin_channel/origin_instance_name",
      instanceName, kind,
    };
  }

  if (kind === "evolution") {
    if (!env.evolutionUrl || !env.evolutionKey) {
      return {
        unavailable: true, reason: "missing_credentials",
        detail: "EVOLUTION_API_URL/KEY ausentes", instanceName, kind,
      };
    }
    const { data: inst } = await supabase
      .from("whatsapp_instances")
      .select("status, manual_review_required, fatal_lock_until")
      .eq("instance_name", instanceName)
      .maybeSingle();
    if (!inst) {
      return {
        unavailable: true, reason: "instance_not_found",
        detail: `instância ${instanceName} não cadastrada`, instanceName, kind,
      };
    }
    if (inst.manual_review_required) {
      return {
        unavailable: true, reason: "manual_review_required",
        detail: `instância ${instanceName} em revisão manual`, instanceName, kind,
      };
    }
    if (inst.fatal_lock_until && new Date(inst.fatal_lock_until) > new Date()) {
      return {
        unavailable: true, reason: "instance_locked",
        detail: `instância ${instanceName} travada até ${inst.fatal_lock_until}`,
        instanceName, kind,
      };
    }
    const status = String(inst.status || "").toLowerCase();
    if (status && !HEALTHY_STATUSES.has(status)) {
      return {
        unavailable: true, reason: "instance_offline",
        detail: `instância ${instanceName} status=${status}`, instanceName, kind,
      };
    }
    const adapter = getAdapter({
      kind: "evolution",
      input: { apiUrl: env.evolutionUrl, apiKey: env.evolutionKey, instanceName },
    });
    return { kind: "evolution", instanceName, adapter };
  }


  if (!env.whapiToken) {
    return {
      unavailable: true, reason: "missing_credentials",
      detail: "WHAPI_TOKEN ausente", instanceName, kind,
    };
  }
  const adapter = getAdapter({
    kind: "whapi",
    input: { apiToken: env.whapiToken, instanceName },
  });
  return { kind: "whapi", instanceName, adapter };
}

function isUnavailable(
  ch: ResolvedChannel | UnavailableChannel | null,
): ch is UnavailableChannel {
  return !!ch && (ch as UnavailableChannel).unavailable === true;
}

async function guardOk(supabase: any, instanceName: string, label: string): Promise<boolean> {
  const quota = await checkSendQuota(supabase, instanceName);
  if (!quota.allowed) {
    console.warn(`🚫 [channel-sender:${label}] bloqueado ${instanceName} reason=${quota.reason}`);
    return false;
  }
  return true;
}

function ctx(consultantId: string, customerId: string, stage: string): SendContext {
  return {
    customerId: customerId || "auto-progress",
    consultantId,
    stepId: `auto_progress:${stage}`,
    idempotencyKey: `${consultantId}:${customerId}:${stage}:${Date.now()}`,
  };
}

async function sendText(
  supabase: any,
  channel: ResolvedChannel,
  jid: string,
  text: string,
  sendCtx: SendContext,
): Promise<boolean> {
  if (!(await guardOk(supabase, channel.instanceName, "text"))) return false;
  try {
    const r = await channel.adapter.sendText(jid, text, { ...sendCtx, supabase });
    if (!r.ok) {
      console.error(`[${channel.kind}] sendText falhou:`, (r as any).detail);
      return false;
    }
    await registerSend(supabase, channel.instanceName);
    return true;
  } catch (e) {
    console.error(`[${channel.kind}] sendText exception:`, (e as Error)?.message);
    return false;
  }
}

async function sendMedia(
  supabase: any,
  channel: ResolvedChannel,
  jid: string,
  url: string,
  caption: string,
  kind: "image" | "video" | "document",
  sendCtx: SendContext,
): Promise<boolean> {
  if (!(await guardOk(supabase, channel.instanceName, kind))) return false;
  const media =
    kind === "document"
      ? { kind, url, filename: "arquivo", caption }
      : { kind, url, caption };
  try {
    const r = await channel.adapter.sendMedia(jid, media as any, sendCtx);
    if (!r.ok) {
      console.error(`[${channel.kind}] sendMedia(${kind}) falhou:`, (r as any).detail);
      return false;
    }
    await registerSend(supabase, channel.instanceName);
    return true;
  } catch (e) {
    console.error(`[${channel.kind}] sendMedia(${kind}) exception:`, (e as Error)?.message);
    return false;
  }
}

async function sendAudio(
  supabase: any,
  channel: ResolvedChannel,
  jid: string,
  url: string,
  sendCtx: SendContext,
): Promise<boolean> {
  if (!(await guardOk(supabase, channel.instanceName, "audio"))) return false;
  try {
    const r = await channel.adapter.sendMedia(jid, { kind: "audio", url, ptt: true }, sendCtx);
    if (!r.ok) {
      console.error(`[${channel.kind}] sendAudio falhou:`, (r as any).detail);
      return false;
    }
    await registerSend(supabase, channel.instanceName);
    return true;
  } catch (e) {
    console.error(`[${channel.kind}] sendAudio exception:`, (e as Error)?.message);
    return false;
  }
}

async function sendAudioWithRetry(
  supabase: any,
  channel: ResolvedChannel,
  jid: string,
  url: string,
  sendCtx: SendContext,
): Promise<boolean> {
  const ok = await sendAudio(supabase, channel, jid, url, sendCtx);
  if (ok) return true;
  if (channel.kind !== "evolution") return false;

  await new Promise((r) => setTimeout(r, 1500));
  return await sendAudio(supabase, channel, jid, url, sendCtx);
}

async function renderVoiceTemplate(
  supabase: any,
  voiceTemplateId: string,
  name: string,
): Promise<string | null> {
  try {
    const { data, error } = await supabase.functions.invoke("voice-template-stitch", {
      body: { action: "render", template_id: voiceTemplateId, name: name || "", variables: {} },
    });
    if (error) return null;
    if ((data as any)?.error) return null;
    return (data as any)?.url || null;
  } catch {
    return null;
  }
}

interface MsgConfig {
  message_type: string;
  message_text: string | null;
  media_url: string | null;
  image_url: string | null;
  voice_template_id?: string | null;
}

interface SendResult {
  preview: string;
  image_ok: boolean | null;
  audio_ok: boolean | null;
  text_ok: boolean | null;
}

function emptyResult(): SendResult {
  return { preview: "", image_ok: null, audio_ok: null, text_ok: null };
}

function formatSendStatus(r: SendResult): { status: string; tag: string } {
  const parts: string[] = [];
  if (r.image_ok !== null) parts.push(`img:${r.image_ok ? "ok" : "fail"}`);
  if (r.audio_ok !== null) parts.push(`audio:${r.audio_ok ? "ok" : "fail"}`);
  if (r.text_ok !== null) parts.push(`text:${r.text_ok ? "ok" : "fail"}`);
  const tag = parts.length ? `[${parts.join("|")}]` : "";

  const fails: string[] = [];
  if (r.image_ok === false) fails.push("image");
  if (r.audio_ok === false) fails.push("audio");
  if (r.text_ok === false) fails.push("text");
  const total = [r.image_ok, r.audio_ok, r.text_ok].filter((v) => v !== null).length;
  if (total === 0) return { status: "no_content", tag };
  if (fails.length === 0) return { status: "sent", tag };
  if (fails.length === total) return { status: "failed", tag };
  return { status: `partial:${fails.join("+")}_missing`, tag };
}

async function sendSingleMessage(
  supabase: any,
  channel: ResolvedChannel,
  jid: string,
  phone: string,
  msg: MsgConfig,
  sendCtx: SendContext,
  customerName?: string,
): Promise<SendResult> {
  const displayName = customerName || phone;
  const messageText = (msg.message_text || "")
    .replace(/\{\{nome\}\}/g, displayName)
    .replace(/\{\{telefone\}\}/g, phone);
  const msgType = msg.message_type || "text";

  const result: SendResult = emptyResult();


  if (msg.image_url && msgType !== "image") {
    result.image_ok = await sendMedia(supabase, channel, jid, msg.image_url, "", "image", sendCtx);
  }

  let audioUrl = msg.media_url;
  if (msgType === "audio" && msg.voice_template_id) {
    const rendered = await renderVoiceTemplate(supabase, msg.voice_template_id, customerName || "");
    if (rendered) audioUrl = rendered;
  }

  if (msgType === "audio" && audioUrl) {
    result.audio_ok = await sendAudioWithRetry(supabase, channel, jid, audioUrl, sendCtx);


    if (result.audio_ok === false) {
      await sendText(supabase, channel, jid, `🎧 Áudio: ${audioUrl}`, sendCtx);
    }
    if (messageText) {
      result.text_ok = await sendText(supabase, channel, jid, messageText, sendCtx);
    }
  } else if (msgType === "image" && msg.media_url) {
    result.image_ok = await sendMedia(supabase, channel, jid, msg.media_url, messageText, "image", sendCtx);
    if (messageText) result.text_ok = result.image_ok;
  } else if (msgType === "video" && msg.media_url) {
    const ok = await sendMedia(supabase, channel, jid, msg.media_url, messageText, "video", sendCtx);
    result.image_ok = ok;
    if (messageText) result.text_ok = ok;
  } else if (messageText) {
    result.text_ok = await sendText(supabase, channel, jid, messageText, sendCtx);
  }

  result.preview = messageText || "[mídia]";
  return result;
}

function mergeResults(a: SendResult, b: SendResult): SendResult {
  const merge = (x: boolean | null, y: boolean | null): boolean | null => {
    if (x === null) return y;
    if (y === null) return x;
    return x && y;
  };
  return {
    preview: b.preview || a.preview,
    image_ok: merge(a.image_ok, b.image_ok),
    audio_ok: merge(a.audio_ok, b.audio_ok),
    text_ok: merge(a.text_ok, b.text_ok),
  };
}

async function sendStageAutoMessages(
  supabase: any,
  channel: ResolvedChannel,
  jid: string,
  phone: string,
  stageData: any,
  consultantId: string,
  customerId: string,
  rejectionReason?: string | null,
  dealOrigin?: string | null,
  customerName?: string,
): Promise<SendResult> {
  const sendCtx = ctx(consultantId, customerId, stageData.stage_key);

  const { data: multiMsgs } = await supabase
    .from("stage_auto_messages")
    .select("*")
    .eq("stage_id", stageData.id)
    .order("position", { ascending: true });

  const filtered = (multiMsgs || []).filter((m: any) => {
    const reasonMatch = !m.rejection_reason || m.rejection_reason === rejectionReason;
    const originMatch = !m.deal_origin || m.deal_origin === dealOrigin;
    return reasonMatch && originMatch;
  });

  let acc: SendResult = emptyResult();

  if (filtered.length > 0) {
    for (let i = 0; i < filtered.length; i++) {
      const msg = filtered[i];
      if (i > 0 && msg.delay_seconds > 0) {
        await new Promise((r) => setTimeout(r, msg.delay_seconds * 1000));
      }
      const r = await sendSingleMessage(supabase, channel, jid, phone, msg, sendCtx, customerName);
      acc = mergeResults(acc, r);
    }
  } else {
    const hasContent = stageData.auto_message_text || stageData.auto_message_media_url || stageData.auto_message_image_url;
    if (!hasContent) return acc;
    acc = await sendSingleMessage(supabase, channel, jid, phone, {
      message_type: stageData.auto_message_type,
      message_text: stageData.auto_message_text,
      media_url: stageData.auto_message_media_url,
      image_url: stageData.auto_message_image_url,
    }, sendCtx, customerName);
  }

  return acc;
}

function isValidJid(jid: string): boolean {
  if (!jid) return false;
  if (jid === "status@broadcast") return false;
  if (/sem_celular/i.test(jid)) return false;
  const phone = jid.split("@")[0];
  return phone.replace(/\D/g, "").length >= 8;
}

function normalizePhone(raw: string): string {
  const digits = String(raw || "").replace(/\D/g, "");
  if (digits.startsWith("55") && digits.length >= 12) return digits;
  if (digits.length === 11) return `55${digits}`;
  if (digits.length === 10) return `55${digits}`;
  return digits;
}

function toJid(raw: string): string {
  if (!raw) return raw;
  if (raw.includes("@")) return raw;
  return `${normalizePhone(raw)}@s.whatsapp.net`;
}

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-internal-secret",
};

const json = (b: unknown, s = 200) =>
  new Response(JSON.stringify(b), {
    status: s,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });

function gatesAllowLive(g: {
  toggleOn: boolean;
  settingsEnabled: boolean;
  liveDispatchEnabled: boolean;
  botGlobalEnabled: boolean;
}): boolean {
  return g.toggleOn && g.settingsEnabled && g.liveDispatchEnabled && g.botGlobalEnabled;
}
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    const internalSecret = req.headers.get("x-internal-secret") || "";
    let expectedInternal = Deno.env.get("EMBED_INTERNAL_SECRET") || "";
    if (!expectedInternal) {
      const { data: s } = await supabase
        .from("settings")
        .select("value")
        .eq("key", "embed_internal_token")
        .maybeSingle();
      expectedInternal = String(s?.value || "");
    }
    const isInternal = !!expectedInternal && !!internalSecret && internalSecret === expectedInternal;

    if (!isInternal) {
      const authz = req.headers.get("authorization") || "";
      const jwt = authz.replace(/^Bearer\s+/i, "");
      if (!jwt) return json({ error: "unauthorized" }, 401);
      const { data: userData } = await supabase.auth.getUser(jwt);
      if (!userData?.user) return json({ error: "unauthorized" }, 401);
      const { data: roleRow } = await supabase
        .from("user_roles")
        .select("role")
        .eq("user_id", userData.user.id)
        .eq("role", "admin")
        .maybeSingle();
      if (!roleRow) return json({ error: "forbidden" }, 403);
    }

    let body: { dryRun?: boolean; preview?: boolean; time?: string } = {};
    try {
      body = await req.json();
    } catch {
      body = {};
    }

    const forceDry = body.dryRun === true;
    const preview = body.preview === true;

    const toggleOn = await isAutomationEnabled(supabase, "daily_reheat");
    if (!toggleOn && !preview) {
      await logSkipped(supabase, "daily_reheat", { dryRun: true, source: "cron_or_call" });
      return json({ ok: true, skipped: "automation_disabled", key: "daily_reheat", dryRun: true });
    }

    const botGlobal = await isBotGloballyEnabled(supabase);
    const settings = await loadDailyReheatSettings(supabase);
    const gates = {
      toggleOn,
      settingsEnabled: !!settings.enabled,
      liveDispatchEnabled: !!settings.live_dispatch_enabled,
      botGlobalEnabled: botGlobal,
    };
    const live = !forceDry && gatesAllowLive(gates);
    const dryRun = !live;
    const cycleDate = cycleDateBRT();
    const window = isWithinCommercialWindow(settings);
    const quiet = isQuietHourBRT();

    if (quiet || !window.ok) {
      const reason = quiet ? "quiet_hours" : window.reason || "outside_window";
      await supabase.from("daily_reheat_runs").insert({
        dry_run: dryRun,
        meta: {
          skipped: reason,
          cycle_date: cycleDate,
          preview,
          gates,
          live,
        },
      });
      return json({ ok: true, skipped: reason, dryRun, live, cycleDate, gates });
    }

    const { plans: newPlans, skippedGuards, skippedCap, scannedA, scannedB } =
      await planDailyReheat(supabase, settings, { cycleDate });

    const { data: runRow, error: runErr } = await supabase
      .from("daily_reheat_runs")
      .insert({
        dry_run: dryRun,
        candidates_a: newPlans.filter((p) => p.queue === "A").length,
        candidates_b: newPlans.filter((p) => p.queue === "B").length,
        would_send_whapi: newPlans.filter((p) => p.would_consume_whapi).length,
        would_call: newPlans.filter((p) => p.would_call).length,
        would_sms: newPlans.filter((p) => p.would_sms).length,
        skipped_cap: skippedCap,
        skipped_guards: skippedGuards,
        meta: {
          cycle_date: cycleDate,
          preview,
          gates,
          live,
          scanned_a: scannedA,
          scanned_b: scannedB,
          daily_whapi_cap: settings.daily_whapi_cap,
          flow_variant: settings.flow_variant,
          pilot_consultant_ids: settings.pilot_consultant_ids,
          sample: newPlans.slice(0, 15).map((p) => ({
            customer_id: p.customer_id,
            queue: p.queue,
            step: p.step,
            phone_tail: p.phone_tail,
            actions: p.planned_actions,
            reason: p.reason,
          })),
        },
      })
      .select("id")
      .maybeSingle();

    if (runErr) {
      console.error("[daily-reheat] run insert failed", runErr.message);
      return json({ ok: false, error: runErr.message }, 500);
    }

    const runId = (runRow as { id?: string } | null)?.id;
    const nowIso = new Date().toISOString();

    if (newPlans.length > 0 && runId) {
      const rows = newPlans.map((p) => ({
        customer_id: p.customer_id,
        consultant_id: p.consultant_id,
        queue: p.queue,
        cycle_date: cycleDate,
        step: p.step,
        status: "planned",
        planned_actions: p.planned_actions,
        next_action_at: nowIso,
        run_id: runId,
      }));
      const { error: qErr } = await supabase.from("daily_reheat_queue").upsert(rows, {
        onConflict: "customer_id,cycle_date",
        ignoreDuplicates: true,
      });
      if (qErr) console.warn("[daily-reheat] queue upsert", qErr.message);
    }

    const duePlans = await loadDueQueuePlans(supabase, { cycleDate });

    let dispatchResult: { dispatched: number; failed: number; details: unknown[] } | null = null;

    if (live && duePlans.length > 0) {
      const { dispatchPlans } = await import("../_shared/daily-reheat/dispatch.ts");
      const env = {
        whapiToken: Deno.env.get("WHAPI_TOKEN") || "",
        whapiBaseUrl: Deno.env.get("WHAPI_BASE_URL") || "https://gate.whapi.cloud",
        evolutionUrl: Deno.env.get("EVOLUTION_API_URL") || "",
        evolutionKey: Deno.env.get("EVOLUTION_API_KEY") || "",
      };
      const { data: settingsRows } = await supabase.from("settings").select("key, value");
      for (const s of settingsRows || []) {
        if (s.key === "whapi_token" && !env.whapiToken) env.whapiToken = String(s.value || "");
        if (s.key === "whapi_api_url" && s.value) env.whapiBaseUrl = String(s.value);
      }

      dispatchResult = await dispatchPlans(supabase, duePlans, settings, env);

      if (runId) {
        await supabase
          .from("daily_reheat_runs")
          .update({
            meta: {
              cycle_date: cycleDate,
              gates,
              live: true,
              due: duePlans.length,
              dispatched: dispatchResult.dispatched,
              failed: dispatchResult.failed,
              details: dispatchResult.details.slice(0, 30),
            },
          })
          .eq("id", runId);
      }
    }

    console.log(
      JSON.stringify({
        level: "info",
        event: live ? "daily_reheat_live" : "daily_reheat_plan_only",
        run_id: runId,
        cycleDate,
        newPlans: newPlans.length,
        due: duePlans.length,
        dispatched: dispatchResult?.dispatched ?? 0,
        gates,
        live,
        preview,
      }),
    );

    return json({
      ok: true,
      dryRun,
      live,
      phase: live ? 1 : 0,
      dispatched: dispatchResult?.dispatched ?? 0,
      failed: dispatchResult?.failed ?? 0,
      cycleDate,
      runId,
      candidatesA: newPlans.filter((p) => p.queue === "A").length,
      candidatesB: newPlans.filter((p) => p.queue === "B").length,
      dueCount: duePlans.length,
      wouldSendWhapi: duePlans.filter((p) => p.would_consume_whapi).length,
      wouldCall: duePlans.filter((p) => p.would_call).length,
      wouldSms: duePlans.filter((p) => p.would_sms).length,
      skippedCap,
      skippedGuards,
      scannedA,
      scannedB,
      gates,
      botGlobalEnabled: botGlobal,
      settingsEnabled: settings.enabled,
      toggleOn,
      preview,
      hint: live
        ? "Envio ativo (cadeados ON)."
        : "Só planejamento. Para enviar: áudio no kit + ligar os 3 interruptores do motor.",
      sample: duePlans.slice(0, 10),
      dispatchDetails: dispatchResult?.details?.slice(0, 10) ?? [],
    });
  } catch (e) {
    console.error("[daily-reheat] fatal", (e as Error).message);
    return json({ ok: false, error: (e as Error).message }, 500);
  }
});
